function buildChecklist(o){
  o=o||{};
  var scope=String(o.scope||'中').trim()||'中';
  var risk=String(o.risk||'中').trim()||'中';
  var lang=String(o.lang||'').trim();
  var title=String(o.title||'').trim();
  var sections=[];
  sections.push({name:'通用检查', items:['代码风格与可读性','单元测试覆盖','错误处理与边界条件','日志与监控埋点','必要文档与注释']});
  if(scope==='中'||scope==='大'){
    sections.push({name:'模块与接口', items: scope==='大'?['架构影响评估','依赖与版本变更审查','向下兼容 / API 兼容性']:['模块间接口与契约']});
  }
  if(risk==='中'||risk==='高'){
    var perf= risk==='高'?'性能（时间/空间复杂度、N+1、缓存命中）':'性能影响评估';
    var items=[];
    if(risk==='高'){ items=['安全（注入 / XSS / 越权 / 密钥管理）', perf, '数据迁移与回滚方案', '灰度 / AB 与监控告警', '容量评估与压测']; }
    else { items=['数据一致性与幂等', perf]; }
    sections.push({name:'风险相关', items:items});
  }
  var rev = risk==='高'?'建议至少 2 名 reviewer（含 1 名资深工程师），并安排 pairwise 评审':(risk==='中'?'建议 1-2 名 reviewer':'建议 1 名 reviewer 即可');
  var lines=[];
  lines.push('# 代码评审清单'+(title?('：'+title):''));
  lines.push('');
  lines.push('- 改动规模：'+scope+'　风险等级：'+risk+(lang?('　语言：'+lang):''));
  lines.push('- 评审人建议：'+rev);
  lines.push('');
  var total=0;
  sections.forEach(function(s){
    lines.push('## '+s.name);
    s.items.forEach(function(it){ lines.push('- [ ] '+it); total++; });
    lines.push('');
  });
  var hasSecurity= sections.some(function(s){return s.items.some(function(it){return it.indexOf('安全')>=0;});});
  return {title:title||'代码评审', itemCount:total, sectionCount:sections.length, risk:risk, hasSecurity:hasSecurity, markdown:lines.join('\n')};
}
var EXPORTS={buildChecklist:buildChecklist};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CodeReviewForgePure = EXPORTS; }
